def merge_sorted_streams(*streams):
    def merge_key(key):
        for s in streams:
            for k, v in s:
                if key in k:
                    return v
        return None

    def merge(current, next_stream):
        for key, value in next_stream:
            if key in current:
                current[key] = max(current[key], value)
            else:
                current[key] = value
        yield from current

    for stream in streams:
        yield from merge_sorted_streams(stream)

